package com.crm.invoice;
import com.crm.invoice.config.SecurityConfig;import com.crm.invoice.controller.InvoiceWorkController;import com.crm.invoice.service.*;import com.crm.invoice.exception.GlobalExceptionHandler;import com.crm.security.*;import org.junit.jupiter.api.*;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.ValueSource;import org.springframework.context.annotation.*;import org.springframework.mock.web.MockServletContext;import org.springframework.web.context.support.AnnotationConfigWebApplicationContext;import org.springframework.web.servlet.config.annotation.EnableWebMvc;import org.springframework.test.web.servlet.MockMvc;import java.time.Instant;import java.util.List;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.setup.MockMvcBuilders.webAppContextSetup;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
/** Production security filters and MVC; Identity/domain mocked, no server or database. */
class InvoiceWorkSecurityTest {
 AnnotationConfigWebApplicationContext context;MockMvc mvc;AccountValidationClient validation;InvoicePresentationService documents;InvoiceFollowupService followup;InvoiceReconciliationService reconcile;
 @Configuration @EnableWebMvc static class Beans {
 @Bean jakarta.persistence.EntityManagerFactory entityManagerFactory(){return mock(jakarta.persistence.EntityManagerFactory.class);}
 @Bean AccountValidationClient validation(){return mock(AccountValidationClient.class);}@Bean JwtAuthenticationFilter jwt(AccountValidationClient c){return new JwtAuthenticationFilter(c);}@Bean RestAuthenticationEntryPoint entry(){return new RestAuthenticationEntryPoint();}@Bean CustomAccessDeniedHandler denied(){return new CustomAccessDeniedHandler();}
 @Bean InvoicePresentationService documents(){return mock(InvoicePresentationService.class);}@Bean InvoiceFollowupService followup(){return mock(InvoiceFollowupService.class);}@Bean InvoiceReconciliationService reconcile(){return mock(InvoiceReconciliationService.class);}@Bean InvoiceWorkController controller(InvoicePresentationService d,InvoiceFollowupService f,InvoiceReconciliationService r){return new InvoiceWorkController(d,f,r);}@Bean GlobalExceptionHandler errors(){return new GlobalExceptionHandler();}}
 @BeforeEach void setup(){context=new AnnotationConfigWebApplicationContext();context.setServletContext(new MockServletContext());context.register(Beans.class,SecurityConfig.class);context.refresh();validation=context.getBean(AccountValidationClient.class);documents=context.getBean(InvoicePresentationService.class);followup=context.getBean(InvoiceFollowupService.class);reconcile=context.getBean(InvoiceReconciliationService.class);mvc=webAppContextSetup(context).addFilters(context.getBean("springSecurityFilterChain",jakarta.servlet.Filter.class)).build();}
 @AfterEach void close(){context.close();org.springframework.security.core.context.SecurityContextHolder.clearContext();}
 void role(String role){when(validation.validate(any())).thenReturn(new AccountValidationResult(AccountValidationResult.Status.VALID,new JwtService.AccessTokenClaims(42,"synthetic",List.of(role),Instant.now().plusSeconds(3600))));}
 @ParameterizedTest @ValueSource(strings={"ADMIN","SUPER_ADMIN","EMPLOYEE","CLIENT"}) void administrationIsClosedToPersonalRolesForAllMethods(String role)throws Exception{
 role(role);int expected=role.equals("ADMIN")||role.equals("SUPER_ADMIN")?200:403;
 for(String path:List.of("/templates","/policy","/reconciliations","/reminders"))mvc.perform(get("/api/invoices/work"+path).header("Authorization","Bearer synthetic")).andExpect(status().is(expected));
 mvc.perform(patch("/api/invoices/work/templates/1/active").header("Authorization","Bearer synthetic").contentType("application/json").content("{\"active\":false}")).andExpect(status().is(expected));
 mvc.perform(post("/api/invoices/work/1/archive").header("Authorization","Bearer synthetic")).andExpect(status().is(expected));
 if(expected==403)verifyNoInteractions(documents,followup,reconcile);
 }
 @Test void identityFailuresNeverReachBusinessServices()throws Exception{when(validation.validate(any())).thenReturn(AccountValidationResult.invalid());mvc.perform(get("/api/invoices/work/templates")).andExpect(status().isUnauthorized());when(validation.validate(any())).thenReturn(AccountValidationResult.unavailable());mvc.perform(get("/api/invoices/work/templates")).andExpect(status().isServiceUnavailable());verifyNoInteractions(documents,followup,reconcile);}
 @Test void noStoreAndInputErrorsAreExplicit()throws Exception{role("ADMIN");mvc.perform(get("/api/invoices/work/templates").header("Authorization","Bearer synthetic")).andExpect(header().string("Cache-Control","no-store"));mvc.perform(get("/api/invoices/work/invoices?from=invalid&to=2026-11-07").header("Authorization","Bearer synthetic")).andExpect(status().isBadRequest());mvc.perform(post("/api/invoices/work/1/issue").header("Authorization","Bearer synthetic").contentType("application/json").content("{\"templateId\":\"not-an-id\"}")).andExpect(status().isBadRequest());mvc.perform(post("/api/invoices/work/reconciliations").header("Authorization","Bearer synthetic").contentType("application/json").content("{}")).andExpect(status().isBadRequest());verifyNoInteractions(followup,reconcile);}
 @Test void sourceBearerIsForwardedAndPrivateFailureBodyIsRemoved()throws Exception{role("ADMIN");when(reconcile.candidates("101","TND",0,"Bearer synthetic")).thenThrow(new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"private source body"));mvc.perform(get("/api/invoices/work/fee-candidates?customerId=101&currency=TND").header("Authorization","Bearer synthetic")).andExpect(status().isServiceUnavailable()).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("private source body"))));verify(reconcile).candidates("101","TND",0,"Bearer synthetic");}
}
